begin;
create table if not exists public.user_follows(follower_id uuid not null references auth.users(id) on delete cascade,followed_id uuid not null references auth.users(id) on delete cascade,status text not null default 'ACCEPTED' check(status in('PENDING','ACCEPTED')),created_at timestamptz not null default now(),primary key(follower_id,followed_id),constraint user_follow_not_self check(follower_id<>followed_id));
create table if not exists public.user_blocks(blocker_id uuid not null references auth.users(id) on delete cascade,blocked_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),primary key(blocker_id,blocked_id),constraint user_block_not_self check(blocker_id<>blocked_id));
create table if not exists public.ranking_likes(ranking_id uuid not null references public.rankings(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),primary key(ranking_id,user_id));
create table if not exists public.ranking_comments(id uuid primary key default gen_random_uuid(),ranking_id uuid not null references public.rankings(id) on delete cascade,author_id uuid not null references auth.users(id) on delete cascade,parent_comment_id uuid references public.ranking_comments(id) on delete cascade,body text not null check(char_length(body) between 1 and 4000),edited_at timestamptz,deleted_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.content_reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references auth.users(id) on delete cascade,target_type text not null check(target_type in('USER','RANKING','COMMENT','CATALOG_ENTITY')),target_id uuid not null,reason text not null,details text,status text not null default 'OPEN' check(status in('OPEN','IN_REVIEW','RESOLVED','DISMISSED')),assigned_to uuid references auth.users(id) on delete set null,resolution_note text,created_at timestamptz not null default now(),resolved_at timestamptz);
create table if not exists public.user_notifications(id uuid primary key default gen_random_uuid(),recipient_id uuid not null references auth.users(id) on delete cascade,actor_id uuid references auth.users(id) on delete set null,notification_type text not null,payload jsonb not null default '{}'::jsonb,read_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.transactional_outbox(id uuid primary key default gen_random_uuid(),event_type text not null,aggregate_type text not null,aggregate_id uuid not null,payload jsonb not null,idempotency_key text not null unique,status text not null default 'PENDING' check(status in('PENDING','PROCESSING','DELIVERED','FAILED')),attempts integer not null default 0 check(attempts>=0),available_at timestamptz not null default now(),locked_at timestamptz,delivered_at timestamptz,last_error text,created_at timestamptz not null default now());
create index if not exists follows_target_status_idx on public.user_follows(followed_id,status,created_at desc);
create index if not exists ranking_likes_user_idx on public.ranking_likes(user_id,created_at desc);
create index if not exists ranking_comments_thread_idx on public.ranking_comments(ranking_id,created_at);
create index if not exists content_reports_status_created_idx on public.content_reports(status,created_at);
create index if not exists notifications_recipient_unread_idx on public.user_notifications(recipient_id,created_at desc) where read_at is null;
create index if not exists outbox_pending_idx on public.transactional_outbox(status,available_at) where status in('PENDING','FAILED');
alter table public.user_follows enable row level security; alter table public.user_blocks enable row level security; alter table public.ranking_likes enable row level security; alter table public.ranking_comments enable row level security; alter table public.content_reports enable row level security; alter table public.user_notifications enable row level security; alter table public.transactional_outbox enable row level security;
revoke all on public.user_follows,public.user_blocks,public.ranking_likes,public.ranking_comments,public.content_reports,public.user_notifications,public.transactional_outbox from anon,authenticated;
grant select,insert,update,delete on public.user_follows,public.user_blocks to authenticated;
grant select,insert,delete on public.ranking_likes to authenticated;
grant select,insert,update on public.ranking_comments to authenticated;
grant select,update on public.user_notifications to authenticated;
grant all on public.content_reports,public.transactional_outbox to service_role;
create policy follows_read_participant on public.user_follows for select to authenticated using(follower_id=(select auth.uid()) or followed_id=(select auth.uid()));
create policy follows_insert_self on public.user_follows for insert to authenticated with check(follower_id=(select auth.uid()));
create policy follows_delete_self on public.user_follows for delete to authenticated using(follower_id=(select auth.uid()));
create policy follows_accept_recipient on public.user_follows for update to authenticated using(followed_id=(select auth.uid())) with check(followed_id=(select auth.uid()));
create policy blocks_owner_access on public.user_blocks for all to authenticated using(blocker_id=(select auth.uid())) with check(blocker_id=(select auth.uid()));
create policy ranking_likes_read_visible on public.ranking_likes for select to authenticated using(user_id=(select auth.uid()) or exists(select 1 from public.rankings r where r.id=ranking_likes.ranking_id and r.user_id=(select auth.uid())) or exists(select 1 from public.ranking_participants p where p.ranking_id=ranking_likes.ranking_id and p.user_id=(select auth.uid()) and p.invitation_status='ACCEPTED'));
create policy ranking_likes_insert_member on public.ranking_likes for insert to authenticated with check(user_id=(select auth.uid()) and (exists(select 1 from public.rankings r where r.id=ranking_likes.ranking_id and r.user_id=(select auth.uid())) or exists(select 1 from public.ranking_participants p where p.ranking_id=ranking_likes.ranking_id and p.user_id=(select auth.uid()) and p.invitation_status='ACCEPTED')));
create policy ranking_likes_delete_self on public.ranking_likes for delete to authenticated using(user_id=(select auth.uid()));
create policy ranking_comments_read_visible on public.ranking_comments for select to authenticated using(author_id=(select auth.uid()) or exists(select 1 from public.rankings r where r.id=ranking_comments.ranking_id and r.user_id=(select auth.uid())) or exists(select 1 from public.ranking_participants p where p.ranking_id=ranking_comments.ranking_id and p.user_id=(select auth.uid()) and p.invitation_status='ACCEPTED'));
create policy ranking_comments_insert_member on public.ranking_comments for insert to authenticated with check(author_id=(select auth.uid()) and (exists(select 1 from public.rankings r where r.id=ranking_comments.ranking_id and r.user_id=(select auth.uid())) or exists(select 1 from public.ranking_participants p where p.ranking_id=ranking_comments.ranking_id and p.user_id=(select auth.uid()) and p.invitation_status='ACCEPTED')));
create policy ranking_comments_update_author on public.ranking_comments for update to authenticated using(author_id=(select auth.uid())) with check(author_id=(select auth.uid()));
create policy notifications_recipient_access on public.user_notifications for select to authenticated using(recipient_id=(select auth.uid()));
create policy notifications_recipient_update on public.user_notifications for update to authenticated using(recipient_id=(select auth.uid())) with check(recipient_id=(select auth.uid()));
commit;
